import sys
import subprocess
from collections import deque

def main():
    manifest_path = sys.argv[1]
    max_parallel = int(sys.argv[2])

    with open(manifest_path, 'r', encoding='utf-8') as f:
        commands = [line.strip() for line in f if line.strip()]

    active_commands = deque()
    command_index = 0

    while commands or active_commands:
        if len(active_commands) < max_parallel:
            if commands:
                cmd = commands.pop(0)
                active_commands.append((command_index, cmd))
                print(f"START {command_index} {cmd}")
                command_index += 1
            else:
                continue

        if active_commands:
            cmd_index, cmd = active_commands[0]
            try:
                result = subprocess.run(cmd, shell=True, check=True, text=True, capture_output=True)
                print(f"END {cmd_index} {cmd} exit={result.returncode}")
            except subprocess.CalledProcessError as e:
                print(f"END {cmd_index} {cmd} exit=error")
            except Exception:
                print(f"END {cmd_index} {cmd} exit=error")

            active_commands.popleft()

    sys.exit(1 if any('exit=' in line for line in sys.stderr.readlines()) else 0)

if __name__ == "__main__":
    main()

import sys
import subprocess
from queue import Queue
from threading import Thread

def process_commands(manifest_path, max_parallel):
    with open(manifest_path, 'r', encoding='utf-8') as f:
        commands = [line.strip() for line in f if line.strip()]

    command_queue = Queue()
    for idx, cmd in enumerate(commands):
        command_queue.put((idx, cmd))

    active_threads = []
    for _ in range(max_parallel):
        thread = Thread(target=execute_command)
        thread.daemon = True
        active_threads.append(thread)
        thread.start()

    for thread in active_threads:
        thread.join()

    non_zero_exits = []
    for idx, cmd in enumerate(commands):
        non_zero_exits.append((idx, cmd, None))

    for _ in range(len(commands)):
        idx, cmd, exit_code = command_queue.get()
        non_zero_exits[idx] = (idx, cmd, exit_code)

    for idx, _, exit_code in non_zero_exits:
        if exit_code is not None and exit_code != 0:
            print(f"DONE {idx} {commands[idx]} exit={exit_code}")
        elif exit_code is None:
            print(f"DONE {idx} {commands[idx]} exit=error")

    sys.exit(1 if any(exit_code is not None and exit_code != 0 for _, _, exit_code in non_zero_exits) else 0)

def execute_command():
    idx, cmd = command_queue.get()
    try:
        result = subprocess.run(cmd, shell=True, check=True, text=True, capture_output=True)
        print(f"DONE {idx} {cmd} exit={result.returncode}")
    except subprocess.CalledProcessError as e:
        print(f"DONE {idx} {cmd} exit=error")
    except Exception:
        print(f"DONE {idx} {cmd} exit=error")

command_queue = Queue()
process_commands(sys.argv[1], int(sys.argv[2]))
